#include <iostream>
#include <cstddef>

void swapElements(int* const element1Ptr, int* const element2Ptr) {
    int hold = *element1Ptr;
    *element1Ptr = *element2Ptr;
    *element2Ptr = hold;
}

void bubbleSort(int* const array, const std::size_t size) {
    for (std::size_t pass = 0; pass < size - 1; ++pass) {
        for (std::size_t j = 0; j < size - 1; ++j) {
            if (array[j] > array[j + 1]) {
                swapElements(&array[j], &array[j + 1]);
            }
        }
    }
}

int main() {
    const std::size_t SIZE = 10;
    int a[SIZE] = {2, 6, 4, 8, 10, 12, 89, 68, 45, 37};

    std::cout << "Original:";
    for (std::size_t i = 0; i < SIZE; ++i) {
        std::cout << " " << a[i];
    }
    std::cout << "\n";

    bubbleSort(a, SIZE);

    std::cout << "Sorted:";
    for (std::size_t i = 0; i < SIZE; ++i) {
        std::cout << " " << a[i];
    }
    std::cout << "\n";

    return 0;
}

#include <iostream>
#include <cstddef>

std::size_t getDecayedSize(const float* ptr) {
    return sizeof(ptr); // Returns pointer size, NOT array byte size!
}

int main() {
    const std::size_t SIZE = 20;
    float array[SIZE];
    double real[22];

    std::cout << "Array bytes: " << sizeof(array) << "\n";
    std::cout << "Decayed pointer bytes: " << getDecayedSize(array) << "\n";

    std::size_t elementCount = sizeof(real) / sizeof(real[0]);
    std::cout << "Real array element count: " << elementCount << "\n";

    return 0;
}
